// Create Client wizard (Client Management → New Client). One POST /api/superadmin/tenants/ creates
// the tenant (its identifier is generated by the server), the company profile and localization,
// the main branch, the administrator and the module / subscription terms in a single transaction.
// The administrator gets either a password now or a one-time setup link (invitation), fetched
// right after creation from …/users/<id>/invitation/ so the secret is never in the create reply.
//
// Steps only organise the form: nothing is saved until "Create client". A server error jumps back
// to the first step holding a field it names.
import React, { useMemo, useRef, useState } from 'react';
import axios from 'axios';
import {
  Alert, Autocomplete, Box, Button, CircularProgress, Dialog, DialogActions, DialogContent, DialogTitle,
  FormControlLabel, Grid, IconButton, InputAdornment, MenuItem, Step, StepButton, Stepper, Switch, TextField,
  Tooltip, Typography, useMediaQuery,
} from '@mui/material';
import { AutoAwesome as GenerateIcon, Visibility, VisibilityOff, Upload as UploadIcon } from '@mui/icons-material';
import ModuleAccessEditor from './ModuleAccessEditor';
import { API, fetchInvitationLink, generatePassword, isReauth, splitErrors, todayIso } from './clientApi';

const STEPS = [
  { label: 'Client', fields: ['tenant_name', 'owner_name', 'admin_email', 'contact_phone', 'country', 'address',
    'tax_registration_no', 'logo_data_url'] },
  { label: 'Company', fields: ['company_name', 'company_registration_no', 'business_address', 'currency', 'language',
    'time_zone', 'tax_enabled'] },
  { label: 'Main Branch', fields: ['branch_name', 'branch_address', 'branch_phone', 'branch_email'] },
  { label: 'Administrator', fields: ['admin_name', 'admin_username', 'password', 'invite_admin'] },
  { label: 'Modules & Subscription', fields: ['modules', 'settings_features', 'subscription_plan',
    'subscription_starts_on', 'subscription_expires_on', 'max_users', 'max_branches'] },
];
const ALL_FIELDS = STEPS.flatMap((s) => s.fields);
const REQUIRED = { tenant_name: 'Client / organization name', admin_username: 'Admin username' };
const MAX_LOGO_BYTES = 700 * 1024; // the data URL must stay under the server's 1 MB

const addMonths = (iso, months) => {
  const d = new Date(`${iso}T00:00:00`);
  d.setMonth(d.getMonth() + months);
  d.setDate(d.getDate() - 1);
  return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
};
const PLAN_MONTHS = { TRIAL: 0.5, MONTHLY: 1, QUARTERLY: 3, HALF_YEARLY: 6, ANNUAL: 12 };
const suggestedExpiry = (plan, start) => {
  if (!start || !PLAN_MONTHS[plan]) return '';
  if (plan === 'TRIAL') {
    const d = new Date(`${start}T00:00:00`);
    d.setDate(d.getDate() + 13);
    return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
  }
  return addMonths(start, PLAN_MONTHS[plan]);
};

const emptyForm = () => ({
  tenant_name: '', owner_name: '', admin_email: '', contact_phone: '', country: '', address: '',
  tax_registration_no: '', logo_data_url: '',
  company_name: '', company_registration_no: '', business_address: '', currency: '', language: '', time_zone: '',
  tax_enabled: true,
  branch_name: '', branch_address: '', branch_phone: '', branch_email: '',
  admin_name: '', admin_username: '', password: '', invite_admin: false,
  subscription_plan: 'ANNUAL', subscription_starts_on: todayIso(),
  subscription_expires_on: suggestedExpiry('ANNUAL', todayIso()), max_users: '5', max_branches: '1',
});

export default function OnboardClientWizard({ catalog, onClose, onCreated }) {
  const fullScreen = useMediaQuery('(max-width:700px)');
  const [step, setStep] = useState(0);
  const [form, setForm] = useState(emptyForm);
  const [subscription, setSubscription] = useState(() => ({
    package: 'FULL_SUITE', settings_features: null,
    modules: [...(catalog.packages.find((p) => p.key === 'FULL_SUITE')?.modules || [])],
  }));
  const [errors, setErrors] = useState({});
  const [general, setGeneral] = useState('');
  const [saving, setSaving] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  // Localization fields the user picked themselves are not overwritten by a later country change.
  const touched = useRef(new Set());
  const loc = catalog.localization || { countries: [], currencies: [], languages: [], time_zones: [] };
  const country = useMemo(() => loc.countries.find((c) => c.code === form.country), [loc.countries, form.country]);

  const set = (key, value) => {
    setForm((f) => ({ ...f, [key]: value }));
    setErrors((x) => ({ ...x, [key]: undefined }));
  };
  const onText = (key) => (e) => set(key, e.target.value);

  const pickCountry = (code) => {
    const c = loc.countries.find((x) => x.code === code);
    setForm((f) => {
      const next = { ...f, country: code };
      if (c) {
        if (!touched.current.has('currency')) next.currency = c.currency;
        if (!touched.current.has('language')) next.language = c.language;
        if (!touched.current.has('time_zone')) next.time_zone = c.time_zone;
      }
      return next;
    });
    setErrors((x) => ({ ...x, country: undefined, tax_registration_no: undefined }));
  };
  const pickPlan = (plan) => {
    setForm((f) => ({
      ...f, subscription_plan: plan,
      subscription_expires_on: plan === 'PERPETUAL' ? '' : suggestedExpiry(plan, f.subscription_starts_on) || f.subscription_expires_on,
    }));
    setErrors((x) => ({ ...x, subscription_plan: undefined, subscription_expires_on: undefined }));
  };

  const readLogo = (file) => {
    if (!file) return;
    if (!['image/png', 'image/jpeg', 'image/svg+xml'].includes(file.type)) {
      setErrors((x) => ({ ...x, logo_data_url: 'Use a PNG, JPG or SVG image.' }));
      return;
    }
    if (file.size > MAX_LOGO_BYTES) {
      setErrors((x) => ({ ...x, logo_data_url: 'Use an image under 700 KB.' }));
      return;
    }
    const reader = new FileReader();
    reader.onload = () => set('logo_data_url', String(reader.result || ''));
    reader.readAsDataURL(file);
  };

  // Client-side checks for one step (the server re-checks everything).
  const stepErrors = (index) => {
    const out = {};
    STEPS[index].fields.forEach((key) => {
      if (REQUIRED[key] && !String(form[key] || '').trim()) out[key] = `${REQUIRED[key]} cannot be empty.`;
    });
    if (index === 3 && !form.invite_admin && !form.password) out.password = 'Enter a password or send a setup link.';
    if (index === 4) {
      const seats = Number(form.max_users);
      if (!Number.isInteger(seats) || seats < 1) out.max_users = 'Allow at least one user (the admin).';
      if (form.max_branches !== '' && (!Number.isInteger(Number(form.max_branches)) || Number(form.max_branches) < 1)) {
        out.max_branches = 'At least 1, or leave blank for no limit.';
      }
      if (form.subscription_plan !== 'PERPETUAL' && !form.subscription_expires_on) {
        out.subscription_expires_on = 'Enter the end date.';
      }
    }
    return out;
  };

  const goTo = (target) => {
    if (target > step) {
      for (let i = step; i < target; i += 1) {
        const errs = stepErrors(i);
        if (Object.keys(errs).length) { setErrors((x) => ({ ...x, ...errs })); setStep(i); return; }
      }
    }
    setStep(target);
  };

  const submit = async () => {
    if (saving) return;
    for (let i = 0; i < STEPS.length; i += 1) {
      const errs = stepErrors(i);
      if (Object.keys(errs).length) { setErrors((x) => ({ ...x, ...errs })); setStep(i); return; }
    }
    setSaving(true);
    setGeneral('');
    const body = {
      ...form,
      tenant_name: form.tenant_name.trim(), admin_username: form.admin_username.trim(),
      password: form.invite_admin ? '' : form.password,
      max_users: Number(form.max_users), max_branches: form.max_branches === '' ? null : Number(form.max_branches),
      subscription_expires_on: form.subscription_plan === 'PERPETUAL' ? null : (form.subscription_expires_on || null),
      subscription_starts_on: form.subscription_starts_on || null,
      package: subscription.package, modules: subscription.modules,
      ...(subscription.modules.includes('settings') ? { settings_features: subscription.settings_features } : {}),
    };
    try {
      const { data } = await axios.post(API, body);
      let invitation = null;
      if (data.invitation_pending && data.admin_user_id) {
        try {
          invitation = await fetchInvitationLink(`${API}${data.id}/users/`, data.admin_user_id);
        } catch (err) {
          invitation = { error: true };
        }
      }
      onCreated({ tenant: data, password: form.invite_admin ? null : form.password, invitation });
    } catch (err) {
      if (isReauth(err)) return; // the password prompt took over; it retries the request
      const { fields, general: msg } = splitErrors(err, ALL_FIELDS, 'The client could not be created.');
      setErrors(fields);
      setGeneral(msg);
      const first = STEPS.findIndex((s) => s.fields.some((f) => fields[f]));
      if (first >= 0) setStep(first);
    } finally {
      setSaving(false);
    }
  };

  const tf = (key, label, props = {}) => (
    <TextField fullWidth size="small" label={label} value={form[key] ?? ''} onChange={onText(key)}
      required={key in REQUIRED} error={Boolean(errors[key])} helperText={errors[key] || props.helperText || ' '}
      disabled={saving} {...props} />
  );
  const stepHasError = (i) => STEPS[i].fields.some((f) => errors[f]);

  return (
    <Dialog open onClose={saving ? undefined : onClose} maxWidth="md" fullWidth fullScreen={fullScreen}
      aria-labelledby="new-client-title" PaperProps={{ sx: { maxHeight: { sm: 'calc(100vh - 48px)' } } }}>
      <DialogTitle id="new-client-title" sx={{ pb: 1 }}>
        New Client
        <Stepper nonLinear activeStep={step} sx={{ mt: 1.5, ...(fullScreen ? { overflowX: 'auto', pb: 0.5 } : {}) }}
          alternativeLabel={!fullScreen}>
          {STEPS.map((s, i) => (
            <Step key={s.label} completed={false}>
              <StepButton onClick={() => goTo(i)} optional={stepHasError(i)
                ? <Typography variant="caption" color="error">Check</Typography> : null}>
                {s.label}
              </StepButton>
            </Step>
          ))}
        </Stepper>
      </DialogTitle>
      <DialogContent dividers>
        {general && <Alert severity="error" sx={{ mb: 2 }}>{general}</Alert>}

        {step === 0 && (
          <Grid container columnSpacing={2}>
            <Grid item xs={12} sm={6}>{tf('tenant_name', 'Client / Organization Name', { autoFocus: true, inputProps: { maxLength: 150 } })}</Grid>
            <Grid item xs={12} sm={6}>{tf('owner_name', 'Owner Name', { inputProps: { maxLength: 150 } })}</Grid>
            <Grid item xs={12} sm={6}>{tf('admin_email', 'Email', { type: 'email' })}</Grid>
            <Grid item xs={12} sm={6}>{tf('contact_phone', 'Phone', { type: 'tel', inputProps: { maxLength: 20 } })}</Grid>
            <Grid item xs={12} sm={6}>
              <TextField select fullWidth size="small" label="Country" value={form.country} disabled={saving}
                onChange={(e) => pickCountry(e.target.value)} error={Boolean(errors.country)}
                helperText={errors.country || 'Suggests currency, language and time zone'}>
                <MenuItem value="">—</MenuItem>
                {loc.countries.map((c) => <MenuItem key={c.code} value={c.code}>{c.name}</MenuItem>)}
              </TextField>
            </Grid>
            <Grid item xs={12} sm={6}>
              {tf('tax_registration_no', `${country?.tax_reg_label || 'Tax Registration No'}`, {
                inputProps: { maxLength: 30 }, helperText: 'Optional · printed on bills',
              })}
            </Grid>
            <Grid item xs={12}>{tf('address', 'Address', { multiline: true, minRows: 2, inputProps: { maxLength: 1000 } })}</Grid>
            <Grid item xs={12}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, flexWrap: 'wrap' }}>
                <Button component="label" size="small" variant="outlined" startIcon={<UploadIcon />} disabled={saving}>
                  {form.logo_data_url ? 'Change logo' : 'Upload logo'}
                  <input hidden type="file" accept="image/png,image/jpeg,image/svg+xml"
                    onChange={(e) => { readLogo(e.target.files?.[0]); e.target.value = ''; }} />
                </Button>
                {form.logo_data_url && (
                  <>
                    <Box component="img" src={form.logo_data_url} alt="Logo preview"
                      sx={{ height: 40, maxWidth: 140, objectFit: 'contain', border: 1, borderColor: 'divider', borderRadius: 1, p: 0.25 }} />
                    <Button size="small" onClick={() => set('logo_data_url', '')}>Remove</Button>
                  </>
                )}
                <Typography variant="caption" color={errors.logo_data_url ? 'error' : 'text.secondary'}>
                  {errors.logo_data_url || 'PNG, JPG or SVG under 700 KB · used on bills and labels'}
                </Typography>
              </Box>
            </Grid>
          </Grid>
        )}

        {step === 1 && (
          <Grid container columnSpacing={2}>
            <Grid item xs={12} sm={6}>
              {tf('company_name', 'Company Name', { placeholder: form.tenant_name, helperText: 'Blank = same as the client name', inputProps: { maxLength: 150 } })}
            </Grid>
            <Grid item xs={12} sm={6}>{tf('company_registration_no', 'Company Registration Number', { inputProps: { maxLength: 60 } })}</Grid>
            <Grid item xs={12}>
              {tf('business_address', 'Business Address', { multiline: true, minRows: 2, helperText: 'Blank = the client address', inputProps: { maxLength: 1000 } })}
            </Grid>
            <Grid item xs={12} sm={4}>
              <TextField select fullWidth size="small" label="Currency" value={form.currency} disabled={saving}
                onChange={(e) => { touched.current.add('currency'); set('currency', e.target.value); }}
                error={Boolean(errors.currency)} helperText={errors.currency || ' '}>
                <MenuItem value="">Default</MenuItem>
                {loc.currencies.map((c) => <MenuItem key={c.code} value={c.code}>{c.code} · {c.name}</MenuItem>)}
              </TextField>
            </Grid>
            <Grid item xs={12} sm={4}>
              <TextField select fullWidth size="small" label="Language" value={form.language} disabled={saving}
                onChange={(e) => { touched.current.add('language'); set('language', e.target.value); }}
                error={Boolean(errors.language)} helperText={errors.language || ' '}>
                <MenuItem value="">Default</MenuItem>
                {loc.languages.map((l) => <MenuItem key={l.code} value={l.code}>{l.name}</MenuItem>)}
              </TextField>
            </Grid>
            <Grid item xs={12} sm={4}>
              <Autocomplete size="small" options={loc.time_zones.map((z) => z.name)} value={form.time_zone || null}
                disabled={saving}
                onChange={(_, v) => { touched.current.add('time_zone'); set('time_zone', v || ''); }}
                renderInput={(params) => (
                  <TextField {...params} label="Time Zone" error={Boolean(errors.time_zone)} helperText={errors.time_zone || ' '} />
                )} />
            </Grid>
            <Grid item xs={12}>
              <FormControlLabel control={<Switch checked={form.tax_enabled} onChange={(e) => set('tax_enabled', e.target.checked)} />}
                label={`Charge ${country?.tax_label || 'tax'} on bills (tax rates are set up in the client's Settings)`} />
            </Grid>
          </Grid>
        )}

        {step === 2 && (
          <Grid container columnSpacing={2}>
            <Grid item xs={12} sm={6}>{tf('branch_name', 'Main Branch Name', { placeholder: 'Head Office', helperText: 'Blank = Head Office', inputProps: { maxLength: 100 } })}</Grid>
            <Grid item xs={12} sm={6}>{tf('branch_phone', 'Branch Phone', { type: 'tel', inputProps: { maxLength: 20 } })}</Grid>
            <Grid item xs={12} sm={6}>{tf('branch_email', 'Branch Email', { type: 'email' })}</Grid>
            <Grid item xs={12}>{tf('branch_address', 'Branch Address', { multiline: true, minRows: 2, inputProps: { maxLength: 1000 } })}</Grid>
          </Grid>
        )}

        {step === 3 && (
          <Grid container columnSpacing={2}>
            <Grid item xs={12} sm={6}>{tf('admin_name', 'Admin Name', { inputProps: { maxLength: 150 } })}</Grid>
            <Grid item xs={12} sm={6}>
              {tf('admin_username', 'Admin Username', { autoComplete: 'off', inputProps: { maxLength: 150, spellCheck: false } })}
            </Grid>
            <Grid item xs={12}>
              <FormControlLabel control={<Switch checked={form.invite_admin} onChange={(e) => set('invite_admin', e.target.checked)} />}
                label="Send a setup link — the admin chooses their own password (recommended)" />
            </Grid>
            {!form.invite_admin && (
              <Grid item xs={12} sm={6}>
                {tf('password', 'Password', {
                  type: showPassword ? 'text' : 'password', autoComplete: 'new-password',
                  InputProps: {
                    endAdornment: (
                      <InputAdornment position="end">
                        <Tooltip title="Generate a strong password">
                          <IconButton size="small" aria-label="Generate a strong password" disabled={saving}
                            onClick={() => { set('password', generatePassword()); setShowPassword(true); }}>
                            <GenerateIcon fontSize="small" />
                          </IconButton>
                        </Tooltip>
                        <IconButton size="small" edge="end" aria-label={showPassword ? 'Hide password' : 'Show password'}
                          onClick={() => setShowPassword((v) => !v)}>
                          {showPassword ? <VisibilityOff fontSize="small" /> : <Visibility fontSize="small" />}
                        </IconButton>
                      </InputAdornment>
                    ),
                  },
                })}
              </Grid>
            )}
            <Grid item xs={12}>
              <Alert severity="info" sx={{ py: 0.5 }}>
                Initial role: <b>Client Owner (Super Admin)</b> — full access to every module enabled for this client.
                They add the client’s other users and roles; you can also do it later from the client’s Users tab.
                This account is never a platform administrator.
              </Alert>
            </Grid>
          </Grid>
        )}

        {step === 4 && (
          <Box>
            <Grid container columnSpacing={2}>
              <Grid item xs={12} sm={4}>
                <TextField select fullWidth size="small" label="Subscription Plan" value={form.subscription_plan}
                  disabled={saving} onChange={(e) => pickPlan(e.target.value)}
                  error={Boolean(errors.subscription_plan)} helperText={errors.subscription_plan || ' '}>
                  {(catalog.subscription_plans || []).map((p) => <MenuItem key={p.key} value={p.key}>{p.label}</MenuItem>)}
                </TextField>
              </Grid>
              <Grid item xs={6} sm={4}>
                {tf('subscription_starts_on', 'Start Date', { type: 'date', InputLabelProps: { shrink: true } })}
              </Grid>
              <Grid item xs={6} sm={4}>
                {tf('subscription_expires_on', form.subscription_plan === 'TRIAL' ? 'Trial Ends' : 'Expiry Date', {
                  type: 'date', InputLabelProps: { shrink: true }, disabled: saving || form.subscription_plan === 'PERPETUAL',
                  helperText: form.subscription_plan === 'PERPETUAL' ? 'No expiry' : 'Last working day',
                })}
              </Grid>
              <Grid item xs={6} sm={4}>
                {tf('max_users', 'Maximum Users', { type: 'number', inputProps: { min: 1, max: 10000 }, helperText: 'Active accounts, admin included' })}
              </Grid>
              <Grid item xs={6} sm={4}>
                {tf('max_branches', 'Maximum Branches', { type: 'number', inputProps: { min: 1, max: 1000 }, helperText: 'Blank = no limit' })}
              </Grid>
            </Grid>
            <Typography variant="subtitle2" fontWeight={700} sx={{ mt: 0.5, mb: 1 }}>Enabled modules</Typography>
            {(errors.modules || errors.settings_features) && (
              <Alert severity="error" sx={{ mb: 1.5 }}>{errors.modules || errors.settings_features}</Alert>
            )}
            <ModuleAccessEditor catalog={catalog} value={subscription} disabled={saving}
              onChange={(v) => { setSubscription(v); setErrors((x) => ({ ...x, modules: undefined })); }} />
          </Box>
        )}
      </DialogContent>
      <DialogActions sx={{ justifyContent: 'space-between' }}>
        <Button onClick={onClose} disabled={saving}>Cancel</Button>
        <Box sx={{ display: 'flex', gap: 1 }}>
          <Button disabled={saving || step === 0} onClick={() => setStep((s) => s - 1)}>Back</Button>
          {step < STEPS.length - 1 ? (
            <Button variant="contained" onClick={() => goTo(step + 1)} disabled={saving}>Next</Button>
          ) : (
            <Button variant="contained" onClick={submit} disabled={saving}
              startIcon={saving ? <CircularProgress size={16} color="inherit" /> : null}>
              {saving ? 'Creating…' : 'Create client'}
            </Button>
          )}
        </Box>
      </DialogActions>
    </Dialog>
  );
}
